import{_ as t,o as a,c as r,a0 as i}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"Audio Generation Testing Strategy","description":"E2E and unit testing strategy for parallel audio generation.","frontmatter":{"isInternal":true,"type":"Specification","title":"Audio Generation Testing Strategy","description":"E2E and unit testing strategy for parallel audio generation.","tags":["testing","specs","audio"]},"headers":[],"relativePath":"testing/audio_generation_strategy.md","filePath":"testing/audio_generation_strategy.md"}'),o={name:"testing/audio_generation_strategy.md"};function n(s,e,c,l,d,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="audio-generation-testing-strategy" tabindex="-1">Audio Generation Testing Strategy <a class="header-anchor" href="#audio-generation-testing-strategy" aria-label="Permalink to &quot;Audio Generation Testing Strategy&quot;">​</a></h1><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>The Audio Generator has transitioned from a sequential generation model to a parallel, character-grouped batching architecture. This requires robust testing to prevent race conditions and ensure chronological integrity.</p><h2 id="_2-race-conditions-out-of-order-generation" tabindex="-1">2. Race Conditions &amp; Out-of-Order Generation <a class="header-anchor" href="#_2-race-conditions-out-of-order-generation" aria-label="Permalink to &quot;2. Race Conditions &amp; Out-of-Order Generation&quot;">​</a></h2><p>Because audio chunks are processed out of sequence (grouped by character), tests must verify that the resulting <code>audioUrls</code> array in the Firestore draft document perfectly matches the original script <code>vibeMap</code> order.</p><ul><li><strong>Unit Test</strong>: Mock <code>synthesizeSpeech</code> with variable delays to simulate race conditions, and assert that <code>audioUrls[0]</code> matches <code>vibeMap[0]</code>, regardless of which promise resolves first.</li><li><strong>E2E Test</strong>: Execute a multi-character script and verify that the final aggregated audio track aligns correctly with the timeline.</li></ul><h2 id="_3-quota-management" tabindex="-1">3. Quota Management <a class="header-anchor" href="#_3-quota-management" aria-label="Permalink to &quot;3. Quota Management&quot;">​</a></h2><ul><li>Verify that <code>Promise.all</code> batches are small enough (e.g., chunk size of 5) to avoid <code>429 Too Many Requests</code> from Google Cloud TTS.</li><li>Assert that the exponential backoff retry mechanism correctly catches and recovers from quota errors.</li></ul><h2 id="_4-billing-metrics-integrity" tabindex="-1">4. Billing &amp; Metrics Integrity <a class="header-anchor" href="#_4-billing-metrics-integrity" aria-label="Permalink to &quot;4. Billing &amp; Metrics Integrity&quot;">​</a></h2><ul><li>Verify that parallel incrementation of the <code>ttsUsage</code> billing ledger accurately counts the total characters/bytes processed, avoiding read-modify-write lost updates (which are naturally avoided in JS event loop if done correctly, but must be asserted).</li></ul>',10)])])}const m=t(o,[["render",n]]);export{h as __pageData,m as default};
